    /// What desktop OpenGL 4.6 adds to the core profile (4 entry points).
    pub fn load_gl_4_6(&mut self, get: &mut dyn FnMut(&str) -> *const c_void) {
        self.multi_draw_arrays_indirect_count = unsafe { cast(get("glMultiDrawArraysIndirectCount")) };
        self.multi_draw_elements_indirect_count = unsafe { cast(get("glMultiDrawElementsIndirectCount")) };
        self.polygon_offset_clamp = unsafe { cast(get("glPolygonOffsetClamp")) };
        self.specialize_shader = unsafe { cast(get("glSpecializeShader")) };
    }

    /// The whole core profile up to and including `major.minor`.
    pub fn load_gl_core(&mut self, major: i32, minor: i32, get: &mut dyn FnMut(&str) -> *const c_void) {
        if (major, minor) >= (1, 0) {
            self.load_gl_1_0(get);
        }
        if (major, minor) >= (1, 1) {
            self.load_gl_1_1(get);
        }
        if (major, minor) >= (1, 2) {
            self.load_gl_1_2(get);
        }
        if (major, minor) >= (1, 3) {
            self.load_gl_1_3(get);
        }
        if (major, minor) >= (1, 4) {
            self.load_gl_1_4(get);
        }
        if (major, minor) >= (1, 5) {
            self.load_gl_1_5(get);
        }
        if (major, minor) >= (2, 0) {
            self.load_gl_2_0(get);
        }
        if (major, minor) >= (2, 1) {
            self.load_gl_2_1(get);
        }
        if (major, minor) >= (3, 0) {
            self.load_gl_3_0(get);
        }
        if (major, minor) >= (3, 1) {
            self.load_gl_3_1(get);
        }
        if (major, minor) >= (3, 2) {
            self.load_gl_3_2(get);
        }
        if (major, minor) >= (3, 3) {
            self.load_gl_3_3(get);
        }
        if (major, minor) >= (4, 0) {
            self.load_gl_4_0(get);
        }
        if (major, minor) >= (4, 1) {
            self.load_gl_4_1(get);
        }
        if (major, minor) >= (4, 2) {
            self.load_gl_4_2(get);
        }
        if (major, minor) >= (4, 3) {
            self.load_gl_4_3(get);
        }
        if (major, minor) >= (4, 4) {
            self.load_gl_4_4(get);
        }
        if (major, minor) >= (4, 5) {
            self.load_gl_4_5(get);
        }
        if (major, minor) >= (4, 6) {
            self.load_gl_4_6(get);
        }
    }

